def tensor_product(t1, t2, t3):

    # Check if inputs are numpy arrays
    if not isinstance(t1, np.ndarray) or not isinstance(t2, np.ndarray) or not isinstance(t3, np.ndarray):
        raise ValueError('All inputs should be numpy arrays.')

