    for i in np.nditer(t3):
        if not isinstance(i, (int, float, complex)):
            raise ValueError('All elements of the tensors should be integers, floating points or complex numbers.')

    # Calculate tensor product
    result = np.tensordot(t1, t2, axes=0)
