from pymongo import MongoClient, errors
import pandas as pd
import sys
import multiprocessing

# Create connection to MongoDB
class MongoConnection:
    def __init__(self, host='localhost', port=27017):
        try:
            self.client = MongoClient(host, port)
            self.db = self.client['database_name']
        except errors.ServerSelectionTimeoutError as err:
            print(f"pymongo ERROR:", err)
            client = None
            db = None

# Class to manage database transactions
class TransactionManager:
    def __init__(self, db):
        self.db = db
        self.sessions = []

    def start_session(self):
        session = self.db.client.start_session()
        session.start_transaction()
        self.sessions.append(session)
        return session

    def commit(self, session):
        session.commit_transaction()
        self.sessions.remove(session)
        session.end_session()

    def abort(self, session):
        session.abort_transaction()
        self.sessions.remove(session)
        session.end_session()

    def __del__(self):
        for session in self.sessions:
            session.abort_transaction()
            session.end_session()

# Class to handle data fetching and modification
class DataManager:
    def __init__(self, db):
        self.db = db
        self.transaction_manager = TransactionManager(db)

    def fetch_data(self, collection, query, projection=None):
        return pd.DataFrame(list(self.db[collection].find(query, projection)))

    def update_data(self, collection, query, update, multi=False):
        session = self.transaction_manager.start_session()
        try:
            self.db[collection].update_one(query, update, session=session) if not multi else self.db[collection].update_many(query, update, session=session)
            self.transaction_manager.commit(session)
        except:
            self.transaction_manager.abort(session)     

