```python
import numpy as np

def calc_product(arr):
    return np.prod(arr)

def calc_mean(arr):
    return np.mean(arr)

def calc_standard_deviation(arr):
    return np.std(arr)

def calc_sum(arr):
    return np.sum(arr)

def perform_operation(arr, operation = 'sum'):

    operations = {
        'product': calc_product,
        'mean': calc_mean,
        'standard deviation': calc_standard_deviation,
        'sum': calc_sum
    }

    if operation not in operations:
        raise ValueError('InvalidOperation: Operation not supported')

    results = [operations[operation](subarr) for subarr in arr]
    return np.mean(results)
```
