from PIL import Image
import numpy as np

class ImageSteganography():
    def __init__(self):
        pass

    # Convert sting to binary
    def to_bin(self, data):
        return ''.join(f'{ord(i):08b}' for i in data)

    # Convert binary to string
    def from_bin(self, data):
        return ''.join(chr(int(data[i*8:i*8+8],2)) for i in range(len(data)//8))

    # Change the least significant bit of each pixel's R, G, B
    def alter_pixel(self, pix, data):
        datalist = list(self.to_bin(data))
        lendata = len(datalist)
        imdata = iter(pix)

        for pixel in imdata:
            # change the R,G,B values
            r = self.alter_val(pixel[0], datalist)
            g = self.alter_val(pixel[1], datalist)
            b = self.alter_val(pixel[2], datalist)
            yield (r,g,b, pixel[-1])

    # change least significant bit to 1 or 0
    def alter_val(self, val, datalist):
        if datalist:
            return (val & ~1) | int(datalist.pop(0))
        else:
            return val

    # check if more data to hide exists
    def has_data(self, val, data=None):
        datalist = list(data) if data else None
        if datalist:
            return (val & ~1) | int(datalist.pop(0))
        else:
            return val

    # Save data to new image
    def save_img(self, image, data):
        w = image.width
        (x, y) = (0, 0)

        for pixel in self.alter_pixel(image.getdata(), data):
            # Put modified pixels in the new image
            image.putpixel((x, y), pixel)
            if x == w - 1:
                x = 0
                y += 1
            else:
                x += 1

    # Hiding data into an image
    def hide_data(self, image, data):
        image = image.convert('RGBA')

        if image.mode != 'RGBA':
            print("Invalid Image mode, try with 'RGBA'.")
            return False

        if image.size[0]*image.size[1] < len(data):
            print("Insufficient image size for the data.")
            return False

        self.save_img(image, data)
        return image

    # Extracting data from an image
    def extract_data(self, image):
        image = image.convert('RGBA')

        binary_data = ''
        for pixel in image.getdata():
            r, g, b = pixel[:3]
            binary_data += (bin(r)[-1] + bin(g)[-1] + bin(b)[-1])

        # Split by 8-bits
        data = []
        for i in range(len(binary_data)//8):
            byte = binary_data[i*8:(i+1)*8]
            data.append(byte)

        return self.from_bin(''.join(data))

