import numpy as np

def largest_prime_factor(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    return n

def g(n):
    return sum([largest_prime_factor(i) for i in range(n, n + 9)])

def h(n):
    return max([g(i) for i in range(2, n+1)])

